#include <stdio.h>
#include <limits.h>

int main(void)
{
    unsigned int value = UINT_MAX;
    value += 1U;
    printf("%u\n", value);
    return 0;
}

#include <stdio.h>

int main(void)
{
    int i = 2;
    int before = i++;
    int after = ++i;
    printf("%d %d %d\n", before, after, i);
    return 0;
}

